# ---- src/EverythingIsFine/Private/ConvertTo-IRCapability.ps1 ----
function ConvertTo-IRCapability {
    <#
    .SYNOPSIS
        Derives capability flags from the tenant's enabled service plan names.
    .DESCRIPTION
        Pure function (no API calls) so the licence logic can be unit tested.
        Service plan names should be re-verified against real tenants of each tier (see DESIGN.md section 6).
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [string[]]$ServicePlanName,

        [AllowEmptyCollection()]
        [string[]]$SkuPartNumber = @()
    )

    $plans = [System.Collections.Generic.HashSet[string]]::new([string[]]$ServicePlanName, [System.StringComparer]::OrdinalIgnoreCase)

    $entraP2 = $plans.Contains('AAD_PREMIUM_P2')
    $entraP1 = $entraP2 -or $plans.Contains('AAD_PREMIUM')
    $mdoP2   = $plans.Contains('THREAT_INTELLIGENCE')
    $mdoP1   = $mdoP2 -or $plans.Contains('ATP_ENTERPRISE')

    [pscustomobject]@{
        SkuPartNumbers         = @($SkuPartNumber | Sort-Object -Unique)
        ExchangeOnline         = $plans.Contains('EXCHANGE_S_STANDARD') -or $plans.Contains('EXCHANGE_S_ENTERPRISE')
        EntraP1                = $entraP1
        EntraP2                = $entraP2
        DefenderForOfficeP1    = $mdoP1
        DefenderForOfficeP2    = $mdoP2
        AuditPremium           = $plans.Contains('M365_ADVANCED_AUDITING')

        # Derived: which data paths collectors may use.
        SignInLogsViaGraph     = $entraP1
        ConditionalAccess      = $entraP1
        IdentityProtectionRisk = $entraP2
        ThreatExplorer         = $mdoP2

        # Filled in by Get-IRCapability from live checks; $null = not checked / unknown.
        UnifiedAuditLogEnabled = $null
    }
}

# ---- src/EverythingIsFine/Private/Export-IRData.ps1 ----
function Export-IRData {
    <#
    .SYNOPSIS
        Writes collected data into the open case as JSON (source of truth) and CSV (convenience),
        and records a SHA256 for each file in manifest.csv.
    .EXAMPLE
        Export-IRData -Category 'mailbox' -Name 'jsmith_inboxrules' -Source 'EXO:Get-InboxRule' -InputObject $rules
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [ValidatePattern('^[\w\-]+$')]
        [string]$Category,

        [Parameter(Mandatory)]
        [ValidatePattern('^[\w\-\.@]+$')]
        [string]$Name,

        [Parameter(Mandatory)]
        [string]$Source,

        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [AllowNull()]
        [object[]]$InputObject
    )

    if (-not ($script:IRContext -and $script:IRContext.Case)) {
        throw 'No case is open. Run New-IRCase first.'
    }

    $records = @($InputObject | Where-Object { $null -ne $_ })
    $dir = Join-Path $script:IRContext.Case.Path 'raw' $Category
    if (-not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }

    $jsonPath = Join-Path $dir "$Name.json"
    ConvertTo-Json -InputObject $records -Depth 10 | Set-Content -LiteralPath $jsonPath -Encoding utf8
    $written = @($jsonPath)

    if ($records.Count -gt 0) {
        $csvPath = Join-Path $dir "$Name.csv"
        $records | Export-Csv -LiteralPath $csvPath -NoTypeInformation -Encoding utf8
        $written += $csvPath
    }

    foreach ($file in $written) {
        Add-IRManifestEntry -Path $file -Source $Source -RecordCount $records.Count
    }

    Write-IRLog -Level Info -Message "Saved $($records.Count) record(s) to raw/$Category/$Name" -Data @{ Source = $Source }
    $written | ForEach-Object { Get-Item -LiteralPath $_ }
}

function Add-IRManifestEntry {
    <#
    .SYNOPSIS
        Appends a file's SHA256 and metadata to the case's manifest.csv.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Path,

        [string]$Source = '',

        [int]$RecordCount = -1
    )

    $caseRoot = $script:IRContext.Case.Path
    $item = Get-Item -LiteralPath $Path
    [pscustomobject]@{
        RelativePath = [System.IO.Path]::GetRelativePath($caseRoot, $item.FullName)
        SHA256       = (Get-FileHash -LiteralPath $item.FullName -Algorithm SHA256).Hash
        Bytes        = $item.Length
        RecordCount  = $RecordCount
        Source       = $Source
        HashedAtUtc  = (Get-Date).ToUniversalTime().ToString('o')
    } | Export-Csv -LiteralPath (Join-Path $caseRoot 'manifest.csv') -Append -NoTypeInformation -Encoding utf8
}

# ---- src/EverythingIsFine/Private/Get-IRDataRoot.ps1 ----
function Get-IRDataRoot {
    <#
    .SYNOPSIS
        Returns the root folder for tenant profiles and case evidence, creating it if needed.
    .DESCRIPTION
        Evidence must never live inside the git repo. Defaults to ~/EverythingIsFine-Data;
        override with the EIF_DATA_ROOT environment variable (e.g. an encrypted share).
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param()

    $root = if ($env:EIF_DATA_ROOT) { $env:EIF_DATA_ROOT } else { Join-Path $HOME 'EverythingIsFine-Data' }
    if (-not (Test-Path -LiteralPath $root)) {
        New-Item -ItemType Directory -Path $root -Force | Out-Null
    }
    (Resolve-Path -LiteralPath $root).Path
}

# ---- src/EverythingIsFine/Private/Get-IRScopeSet.ps1 ----
function Get-IRScopeSet {
    <#
    .SYNOPSIS
        Returns the Microsoft Graph delegated scopes for the requested permission tier.
    .DESCRIPTION
        ReadOnly is the default for triage and investigation. Elevated adds write scopes
        for containment and must be requested explicitly via Connect-IR -Elevated.
    #>
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [switch]$Elevated
    )

    $readOnly = @(
        'Organization.Read.All'
        'Directory.Read.All'
        'User.Read.All'
        'AuditLog.Read.All'
        'Policy.Read.All'
        'UserAuthenticationMethod.Read.All'
        'Application.Read.All'
        'IdentityRiskEvent.Read.All'
        'IdentityRiskyUser.Read.All'
    )

    $write = @(
        'User.ReadWrite.All'
        'User.RevokeSessions.All'
        'UserAuthenticationMethod.ReadWrite.All'
        'Application.ReadWrite.All'
        'DelegatedPermissionGrant.ReadWrite.All'
        'Policy.ReadWrite.ConditionalAccess'
    )

    if ($Elevated) { $readOnly + $write } else { $readOnly }
}

# ---- src/EverythingIsFine/Private/Read-IRConfirmation.ps1 ----
function Read-IRConfirmation {
    <#
    .SYNOPSIS
        Asks the operator a yes/no question, always prefixed with the tenant domain. Defaults to No.
    #>
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory)]
        [string]$Message
    )

    $domain = if ($script:IRContext) { $script:IRContext.PrimaryDomain } else { 'NO TENANT' }
    $answer = Read-Host "[$domain] $Message (y/N)"
    $answer -match '^(y|yes)$'
}

# ---- src/EverythingIsFine/Private/TenantProfile.ps1 ----
function Get-IRTenantProfilePath {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)]
        [string]$PrimaryDomain
    )

    $dir = Join-Path (Get-IRDataRoot) 'tenants'
    if (-not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    Join-Path $dir "$($PrimaryDomain.ToLowerInvariant()).json"
}

function Get-IRTenantProfile {
    <#
    .SYNOPSIS
        Returns the saved profile for a tenant, or $null if none exists yet.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$PrimaryDomain
    )

    $path = Get-IRTenantProfilePath -PrimaryDomain $PrimaryDomain
    if (Test-Path -LiteralPath $path) {
        Get-Content -LiteralPath $path -Raw | ConvertFrom-Json
    }
}

function Set-IRTenantProfile {
    <#
    .SYNOPSIS
        Writes a tenant profile. Merges with any existing profile so notes are preserved.
    #>
    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter(Mandatory)]
        [string]$PrimaryDomain,

        [Parameter(Mandatory)]
        [string]$TenantId,

        [string]$DisplayName,

        [pscustomobject]$Capability
    )

    $path = Get-IRTenantProfilePath -PrimaryDomain $PrimaryDomain
    $existing = Get-IRTenantProfile -PrimaryDomain $PrimaryDomain

    $profileData = [ordered]@{
        PrimaryDomain  = $PrimaryDomain.ToLowerInvariant()
        TenantId       = $TenantId
        DisplayName    = $DisplayName
        FirstSeenUtc   = if ($existing) { $existing.FirstSeenUtc } else { (Get-Date).ToUniversalTime().ToString('o') }
        LastSeenUtc    = (Get-Date).ToUniversalTime().ToString('o')
        Capability     = $Capability
        Notes          = if ($existing) { $existing.Notes } else { '' }
    }

    if ($PSCmdlet.ShouldProcess($path, 'Write tenant profile')) {
        $profileData | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath $path -Encoding utf8
    }
}

# ---- src/EverythingIsFine/Private/Test-IRModuleDependency.ps1 ----
function Test-IRModuleDependency {
    <#
    .SYNOPSIS
        Returns the names of required modules that are missing or too old. Empty when all present.
    #>
    [CmdletBinding()]
    [OutputType([string[]])]
    param()

    $required = @(
        @{ Name = 'Microsoft.Graph.Authentication';               MinimumVersion = '2.0.0' }
        @{ Name = 'Microsoft.Graph.Identity.DirectoryManagement'; MinimumVersion = '2.0.0' }
        @{ Name = 'Microsoft.Graph.Users';                        MinimumVersion = '2.0.0' }
        @{ Name = 'ExchangeOnlineManagement';                     MinimumVersion = '3.4.0' }
    )

    foreach ($module in $required) {
        $found = Get-Module -ListAvailable -Name $module.Name |
            Where-Object { $_.Version -ge [version]$module.MinimumVersion } |
            Select-Object -First 1
        if (-not $found) { $module.Name }
    }
}

# ---- src/EverythingIsFine/Private/Write-IRLog.ps1 ----
function Write-IRLog {
    <#
    .SYNOPSIS
        Writes a message to the console and, when a case is open, to the case's activity.jsonl.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Message,

        [ValidateSet('Info', 'Warn', 'Finding', 'Action', 'Error')]
        [string]$Level = 'Info',

        [hashtable]$Data
    )

    $colour = @{ Info = 'Gray'; Warn = 'Yellow'; Finding = 'Magenta'; Action = 'Cyan'; Error = 'Red' }[$Level]
    $prefix = if ($script:IRContext) { "[$($script:IRContext.PrimaryDomain)] " } else { '' }
    Write-Host "$prefix$($Level.ToUpper().PadRight(7)) $Message" -ForegroundColor $colour

    if ($script:IRContext -and $script:IRContext.Case) {
        $entry = [ordered]@{
            TimestampUtc = (Get-Date).ToUniversalTime().ToString('o')
            TenantId     = $script:IRContext.TenantId
            Operator     = $script:IRContext.Account
            Level        = $Level
            Message      = $Message
            Data         = $Data
        }
        $line = $entry | ConvertTo-Json -Depth 10 -Compress
        Add-Content -LiteralPath (Join-Path $script:IRContext.Case.Path 'activity.jsonl') -Value $line -Encoding utf8
    }
}

# ---- src/EverythingIsFine/Public/Assert-IRTenant.ps1 ----
function Assert-IRTenant {
    <#
    .SYNOPSIS
        Throws unless the live Graph and Exchange Online sessions both belong to the tenant
        selected with Connect-IR.
    .DESCRIPTION
        Every collector and every containment action calls this first. It is the main protection
        against acting on the wrong client tenant (stale sessions, a second terminal, a mistyped
        domain).
    #>
    [CmdletBinding()]
    param()

    if (-not $script:IRContext) {
        throw 'Not connected to a tenant. Run Connect-IR first.'
    }

    $expected = $script:IRContext.TenantId
    $label = "$($script:IRContext.PrimaryDomain) ($expected)"

    $mg = Get-MgContext
    if (-not $mg -or $mg.TenantId -ne $expected) {
        $actual = if ($mg) { $mg.TenantId } else { 'no session' }
        throw "Tenant guard: Microsoft Graph session is '$actual' but the case tenant is $label. Stopping. Run Connect-IR again."
    }

    if (-not $script:IRContext.SkipExchange) {
        $exo = @(Get-ConnectionInformation | Where-Object { $_.State -eq 'Connected' })
        if ($exo.Count -eq 0) {
            throw "Tenant guard: no Exchange Online session. Case tenant is $label. Run Connect-IR again."
        }
        $wrong = @($exo | Where-Object { $_.TenantID -ne $expected })
        if ($wrong.Count -gt 0) {
            throw "Tenant guard: an Exchange Online session belongs to tenant '$($wrong[0].TenantID)', not $label. Stopping. Run Connect-IR again."
        }
    }
}

# ---- src/EverythingIsFine/Public/Close-IRCase.ps1 ----
function Close-IRCase {
    <#
    .SYNOPSIS
        Closes the open case: stops the transcript, hashes the transcript and activity log, stamps case.json.
    #>
    [CmdletBinding()]
    param()

    if (-not ($script:IRContext -and $script:IRContext.Case)) {
        Write-IRLog -Level Warn -Message 'No case is open.'
        return
    }

    $case = $script:IRContext.Case
    Write-IRLog -Level Action -Message "Case closed: $($case.Reference)"

    try { Stop-Transcript | Out-Null } catch { Write-Verbose 'No transcript was running.' }

    foreach ($file in 'transcript.txt', 'activity.jsonl') {
        $full = Join-Path $case.Path $file
        if (Test-Path -LiteralPath $full) {
            Add-IRManifestEntry -Path $full -Source 'EverythingIsFine'
        }
    }

    $case.ClosedAtUtc = (Get-Date).ToUniversalTime().ToString('o')
    $case | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath (Join-Path $case.Path 'case.json') -Encoding utf8

    $script:IRContext.Case = $null
    $case
}

# ---- src/EverythingIsFine/Public/Connect-IR.ps1 ----
function Connect-IR {
    <#
    .SYNOPSIS
        Connects to one client tenant (Graph + Exchange Online) with the tenant guard and capability check.
    .DESCRIPTION
        1. Disconnects any existing Graph / EXO session.
        2. Signs in to Graph (interactive browser, process-scoped token cache).
        3. Verifies the requested domain or tenant ID belongs to the tenant signed in to.
        4. Pins the tenant ID on first use; refuses if the domain later resolves to another tenant.
        5. Connects Exchange Online as the same account and verifies its tenant.
        6. Detects licence capabilities and prints what the tenant can and cannot show.
    .PARAMETER Tenant
        Primary or verified domain (contoso.com) or tenant ID (GUID).
    .PARAMETER Elevated
        Requests write scopes for containment. Read-only by default.
    .PARAMETER SkipExchange
        Graph only. Most collectors need Exchange Online; use for troubleshooting.
    .EXAMPLE
        Connect-IR -Tenant contoso.com
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Tenant,

        [switch]$Elevated,

        [switch]$SkipExchange
    )

    $missing = @(Test-IRModuleDependency)
    if ($missing.Count -gt 0) {
        throw "Missing required module(s): $($missing -join ', '). Install with: Install-Module $($missing -join ', ') -Scope CurrentUser"
    }

    Disconnect-IR -Quiet

    $tier = if ($Elevated) { 'ELEVATED (read/write)' } else { 'read-only' }
    Write-IRLog -Level Info -Message "Connecting to Microsoft Graph for '$Tenant' ($tier). Sign in with this client's admin account."

    Connect-MgGraph -TenantId $Tenant -Scopes (Get-IRScopeSet -Elevated:$Elevated) -ContextScope Process -NoWelcome -ErrorAction Stop
    $mg = Get-MgContext
    $org = Get-MgOrganization -ErrorAction Stop | Select-Object -First 1

    $verifiedDomains = @($org.VerifiedDomains | ForEach-Object { $_.Name.ToLowerInvariant() })
    $primaryDomain = ($org.VerifiedDomains | Where-Object { $_.IsDefault } | Select-Object -First 1).Name.ToLowerInvariant()

    $isGuid = $null -ne ($Tenant -as [guid])
    $matchesRequest = if ($isGuid) { $mg.TenantId -eq $Tenant } else { $verifiedDomains -contains $Tenant.ToLowerInvariant() }
    if ($org.Id -ne $mg.TenantId -or -not $matchesRequest) {
        Disconnect-IR -Quiet
        throw "Tenant guard: requested '$Tenant' but signed in to '$($org.DisplayName)' ($($mg.TenantId)). Disconnected."
    }

    $pinned = Get-IRTenantProfile -PrimaryDomain $primaryDomain
    if ($pinned -and $pinned.TenantId -ne $mg.TenantId) {
        Disconnect-IR -Quiet
        throw "Tenant guard: $primaryDomain is pinned to tenant $($pinned.TenantId) but this sign-in is tenant $($mg.TenantId). Disconnected. Investigate before continuing."
    }

    $script:IRContext = [pscustomobject]@{
        TenantId      = $mg.TenantId
        PrimaryDomain = $primaryDomain
        DisplayName   = $org.DisplayName
        Account       = $mg.Account
        Elevated      = [bool]$Elevated
        SkipExchange  = [bool]$SkipExchange
        ConnectedAtUtc = (Get-Date).ToUniversalTime().ToString('o')
        Capability    = $null
        Case          = $null
    }

    if (-not $SkipExchange) {
        Write-IRLog -Level Info -Message "Connecting to Exchange Online as $($mg.Account)."
        Connect-ExchangeOnline -UserPrincipalName $mg.Account -ShowBanner:$false -ErrorAction Stop
    }

    # Verifies the EXO session landed in the same tenant as Graph.
    try { Assert-IRTenant }
    catch { Disconnect-IR -Quiet; throw }

    Write-IRLog -Level Info -Message "Connected: $($org.DisplayName) [$primaryDomain] tenant $($mg.TenantId) as $($mg.Account)."

    $script:IRContext.Capability = Get-IRCapability
    Set-IRTenantProfile -PrimaryDomain $primaryDomain -TenantId $mg.TenantId -DisplayName $org.DisplayName -Capability $script:IRContext.Capability

    $script:IRContext
}

# ---- src/EverythingIsFine/Public/Disconnect-IR.ps1 ----
function Disconnect-IR {
    <#
    .SYNOPSIS
        Disconnects Microsoft Graph and Exchange Online and clears the tenant context.
    .DESCRIPTION
        Connect-IR calls this first so a session for another tenant can never carry over.
        Closes any open case first.
    #>
    [CmdletBinding()]
    param(
        [switch]$Quiet
    )

    if ($script:IRContext -and $script:IRContext.Case) {
        Close-IRCase
    }

    if (Get-Command Disconnect-MgGraph -ErrorAction SilentlyContinue) {
        Disconnect-MgGraph -ErrorAction SilentlyContinue | Out-Null
    }
    if (Get-Command Disconnect-ExchangeOnline -ErrorAction SilentlyContinue) {
        Disconnect-ExchangeOnline -Confirm:$false -ErrorAction SilentlyContinue | Out-Null
    }

    if (-not $Quiet -and $script:IRContext) {
        Write-IRLog -Level Info -Message 'Disconnected from Microsoft Graph and Exchange Online.'
    }
    $script:IRContext = $null
}

# ---- src/EverythingIsFine/Public/Get-IRCapability.ps1 ----
function Get-IRCapability {
    <#
    .SYNOPSIS
        Detects what the connected tenant's licensing and configuration let us see.
    .DESCRIPTION
        Reads subscribed SKUs and their enabled service plans, derives capability flags,
        and checks that unified audit log ingestion is on. Prints a summary unless -Quiet.
    #>
    [CmdletBinding()]
    param(
        [switch]$Quiet
    )

    Assert-IRTenant

    $skus = @(Get-MgSubscribedSku -All | Where-Object { $_.CapabilityStatus -eq 'Enabled' })
    $plans = @(
        $skus |
            ForEach-Object { $_.ServicePlans } |
            Where-Object { $_.ProvisioningStatus -eq 'Success' } |
            ForEach-Object { $_.ServicePlanName } |
            Sort-Object -Unique
    )

    $cap = ConvertTo-IRCapability -ServicePlanName $plans -SkuPartNumber @($skus | ForEach-Object { $_.SkuPartNumber })

    if (-not $script:IRContext.SkipExchange) {
        try {
            # Must run in Exchange Online PowerShell; Security & Compliance PowerShell reports False.
            $cap.UnifiedAuditLogEnabled = [bool](Get-AdminAuditLogConfig -ErrorAction Stop).UnifiedAuditLogIngestionEnabled
        }
        catch {
            Write-IRLog -Level Warn -Message "Could not read audit log config: $($_.Exception.Message)"
        }
    }

    if (-not $Quiet) { Show-IRCapability -Capability $cap }
    $cap
}

function Show-IRCapability {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [pscustomobject]$Capability
    )

    $mark = { param($v) if ($null -eq $v) { '?' } elseif ($v) { 'yes' } else { 'NO' } }

    Write-IRLog -Level Info -Message "Licences: $($Capability.SkuPartNumbers -join ', ')"
    $rows = @(
        @{ Name = 'Unified audit log ingestion'; Value = $Capability.UnifiedAuditLogEnabled; Fallback = 'NONE - no audit history. Critical finding.' }
        @{ Name = 'Sign-in logs via Graph (P1)'; Value = $Capability.SignInLogsViaGraph;     Fallback = 'Using UAL UserLoggedIn events (less detail).' }
        @{ Name = 'Conditional Access (P1)';     Value = $Capability.ConditionalAccess;      Fallback = 'Containment uses per-user block + session revoke.' }
        @{ Name = 'Identity Protection (P2)';    Value = $Capability.IdentityProtectionRisk; Fallback = 'Using toolkit heuristics instead of risk scores.' }
        @{ Name = 'Threat Explorer (MDO P2)';    Value = $Capability.ThreatExplorer;         Fallback = 'Using message trace.' }
        @{ Name = 'Audit (Premium)';             Value = $Capability.AuditPremium;           Fallback = 'Audit Standard retention (180 days).' }
    )

    foreach ($row in $rows) {
        $state = & $mark $row.Value
        $level = if ($row.Value) { 'Info' } elseif ($row.Name -like 'Unified audit*' -and $row.Value -eq $false) { 'Error' } else { 'Warn' }
        $message = "{0,-30} {1,-4}" -f $row.Name, $state
        if (-not $row.Value) { $message += "  -> $($row.Fallback)" }
        Write-IRLog -Level $level -Message $message
    }
}

